import{_ as e,o as t,c as s,a2 as r}from"./chunks/framework.CU6jEZEM.js";const i="/entismax/v4/assets/72da6f0e49088044-20261015000316-fmbs167.Bl_W7Jbm.png",o="/entismax/v4/assets/233ea36ae72ad7c4-20261015000316-6ma6yef.DTpPCk-p.png",n="/entismax/v4/assets/13e4e6dce43e7106-20261015000316-nk9wpdj.CSCTJS_o.png",f=JSON.parse('{"title":"４：数据库同步复制说明","description":"","frontmatter":{"title":"４：数据库同步复制说明","date":"2026-10-14T16:03:17.000Z","lastmod":"2026-10-14T16:03:17.000Z"},"headers":[],"relativePath":"guide/1044.md","filePath":"guide/EntisMAXIV/EntisMaxIV帮助文档/操作说明/罐监控操作/冗余管理/４：数据库同步复制说明.md"}'),_={name:"guide/1044.md"};function l(d,a,c,h,p,m){return t(),s("div",null,[...a[0]||(a[0]=[r('<h1 id="_4-数据库同步复制说明" tabindex="-1">４：数据库同步复制说明 <a class="header-anchor" href="#_4-数据库同步复制说明" aria-label="Permalink to &quot;４：数据库同步复制说明&quot;">​</a></h1><h1 id="_4-数据库同步复制说明-1" tabindex="-1">４：数据库同步复制说明 <a class="header-anchor" href="#_4-数据库同步复制说明-1" aria-label="Permalink to &quot;４：数据库同步复制说明&quot;">​</a></h1><p>４：数据库同步复制说明</p><h3 id="简介" tabindex="-1">简介 <a class="header-anchor" href="#简介" aria-label="Permalink to &quot;简介&quot;">​</a></h3><p>冗余系统二台主机的组态数据必须一致，如果分别在二台电脑上组态完成，工作量较大，且容易出错，所以最佳作法，就是在一台电脑上组态完成后，然后把数据库使用备份还原的方式，同步到另一台电脑</p><h3 id="数据库备份" tabindex="-1">数据库备份 <a class="header-anchor" href="#数据库备份" aria-label="Permalink to &quot;数据库备份&quot;">​</a></h3><p>使用EntisMax自带的数据库管理工具DBTools，连接数据库登录以后，在列表中找到组态完毕后的数据库，点击数据库右键.选择菜单[备份数据库],选择好备份存储目录，备份完毕即可.     然后复制文件到另一台电脑 <img src="'+i+'" alt=""></p><h3 id="数据库还原" tabindex="-1">数据库还原 <a class="header-anchor" href="#数据库还原" aria-label="Permalink to &quot;数据库还原&quot;">​</a></h3><p>复制文件到目标电脑后，在目标电脑上也打开数据库管理工具，同样连接数据库登录后，在目标数据库(如不存在，则执行附加操作)上点击右键,选择菜单[还原到此数据库]，然后选择之前复制的数据库备份文件，执行完还原功能即可 <img src="'+o+'" alt=""></p><h3 id="异常处理" tabindex="-1">异常处理 <a class="header-anchor" href="#异常处理" aria-label="Permalink to &quot;异常处理&quot;">​</a></h3><p>如在执行还原时，出现报“拒绝访问错误”时，请设置备份文件的权限，加入Authenticated Users 完全控制权限,然后再次执行还原操作. <img src="'+n+'" alt=""></p>',11)])])}const b=e(_,[["render",l]]);export{f as __pageData,b as default};
